// Ensure the preferred theme is applied before the page paints to avoid flashes.
(function () {
  const applyTheme = (theme) => {
    const nextTheme = theme === "dark" ? "dark" : "light";
    document.documentElement.dataset.theme = nextTheme;
    document.documentElement.style.colorScheme = nextTheme;
  };

  const resolveTheme = () => {
    const stored = (typeof localStorage !== "undefined" && localStorage.getItem("starlight-theme")) || null;
    if (stored === "dark" || stored === "light") {
      return stored;
    }
    const prefersDark = window.matchMedia?.("(prefers-color-scheme: dark)")?.matches;
    return prefersDark ? "dark" : "light";
  };

  try {
    const initialTheme = resolveTheme();
    applyTheme(initialTheme);

    const prefersDarkQuery = window.matchMedia?.("(prefers-color-scheme: dark)");
    if (prefersDarkQuery?.addEventListener) {
      prefersDarkQuery.addEventListener("change", (event) => {
        const stored = (typeof localStorage !== "undefined" && localStorage.getItem("starlight-theme")) || null;
        if (!stored || stored === "auto") {
          applyTheme(event.matches ? "dark" : "light");
        }
      });
    }
  } catch {
    const prefersDark = window.matchMedia?.("(prefers-color-scheme: dark)")?.matches;
    applyTheme(prefersDark ? "dark" : "light");
  }
})();

// Global initializer that works with ViewTransitions SPA navigations.
// Re-run lightweight setup after each navigation and optionally clean up before swaps.
(function () {
  let initialized = false;

  const init = () => {
    if (initialized) return;
    initialized = true;
    // Example: ensure any singleton scripts are present only once
    // const ensureScript = (src) => {
    //   if (document.querySelector(`script[src="${src}"]`)) return;
    //   const s = document.createElement("script");
    //   s.src = src;
    //   s.defer = true;
    //   document.head.appendChild(s);
    // };
    // Add any vendor scripts here if needed
    // ensureScript('/vendor.js');
  };

  const cleanup = () => {
    // Optional: remove listeners or dispose widgets between page swaps
    initialized = false;
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
  document.addEventListener("astro:page-load", init);
  document.addEventListener("astro:after-swap", init);
  document.addEventListener("astro:before-swap", cleanup);
})();

