// Instant page transition system
(function () {
  "use strict";

  const getPreferredTheme = () => {
    const stored = (typeof localStorage !== "undefined" && localStorage.getItem("starlight-theme")) || "auto";
    if (stored === "dark" || stored === "light") {
      return stored;
    }
    const prefersDark = window.matchMedia?.("(prefers-color-scheme: dark)")?.matches;
    return prefersDark ? "dark" : "light";
  };

  const applyStoredTheme = (targetDocument = document) => {
    const theme = getPreferredTheme();
    const root = targetDocument?.documentElement || document.documentElement;
    if (root) {
      root.dataset.theme = theme;
      root.style.colorScheme = theme === "dark" ? "dark" : "light";
    }
    if (window.StarlightThemeProvider?.updatePickers) {
      window.StarlightThemeProvider.updatePickers(theme);
    }
    return theme;
  };

  applyStoredTheme();

  // Track the current page to prevent unnecessary navigation
  let currentPage = window.location.pathname;
  let isNavigating = false;
  let cleanupTOCListeners = null;

  const throttle = (fn, wait = 80) => {
    let timeout = null;
    let previous = 0;
    let lastArgs;
    let lastThis;

    return function throttled(...args) {
      const now = Date.now();
      lastArgs = args;
      lastThis = this;
      const remaining = wait - (now - previous);

      if (remaining <= 0 || remaining > wait) {
        if (timeout) {
          clearTimeout(timeout);
          timeout = null;
        }
        previous = now;
        fn.apply(lastThis, lastArgs);
        lastArgs = lastThis = null;
      } else if (!timeout) {
        timeout = setTimeout(() => {
          previous = Date.now();
          timeout = null;
          fn.apply(lastThis, lastArgs);
          lastArgs = lastThis = null;
        }, remaining);
      }
    };
  };

  const escapeCSS = (value) => {
    if (typeof value !== "string") return value;
    if (typeof CSS !== "undefined" && typeof CSS.escape === "function") {
      return CSS.escape(value);
    }
    return value.replace(/([!"#$%&'()*+,./:;<=>?@[\]^`{|}~])/g, "\\$1");
  };

  // Prevent any loading effects
  function preventLoadingEffects() {
    // Remove loading classes
    document.body.classList.remove("loading", "page-loading", "transitioning");

    // Ensure content is always visible
    const contentSelectors = [".sl-content", ".sl-main", "main", "article", ".sl-container", ".sl-layout"];

    contentSelectors.forEach((selector) => {
      const elements = document.querySelectorAll(selector);
      elements.forEach((el) => {
        if (el) {
          el.style.opacity = "1";
          el.style.visibility = "visible";
          el.style.display = "block";
          el.style.transform = "none";
          el.style.transition = "none";
          el.style.animation = "none";
        }
      });
    });

    // Ensure sidebar is always visible and stable
    const sidebar = document.querySelector(".sidebar-nav");
    if (sidebar) {
      sidebar.style.opacity = "1";
      sidebar.style.visibility = "visible";
      sidebar.style.transition = "none";
      sidebar.style.animation = "none";
      sidebar.style.willChange = "auto";
      sidebar.style.transform = "translateZ(0)";
      sidebar.style.backfaceVisibility = "hidden";
      sidebar.style.contain = "layout style paint";
    }

    // Prevent any React component re-renders during navigation
    const reactRoots = document.querySelectorAll("[data-reactroot]");
    reactRoots.forEach((root) => {
      if (root) {
        root.style.willChange = "auto";
        root.style.transform = "translateZ(0)";
        root.style.backfaceVisibility = "hidden";
      }
    });
  }

  // Handle Astro page events
  function handlePageLoad() {
    preventLoadingEffects();

    // Force immediate visibility
    requestAnimationFrame(() => {
      preventLoadingEffects();
    });
  }

  function handleAfterSwap() {
    preventLoadingEffects();

    // Double-check after a brief delay
    setTimeout(() => {
      preventLoadingEffects();
    }, 10);
  }

  // Prevent Astro from causing re-renders
  function preventAstroRerenders() {
    // Override any Astro navigation methods that might cause re-renders
    if (window.navigate) {
      const originalNavigate = window.navigate;
      window.navigate = function (...args) {
        // Prevent sidebar re-renders during navigation
        const sidebar = document.querySelector(".sidebar-nav");
        if (sidebar) {
          sidebar.style.pointerEvents = "none";
          setTimeout(() => {
            sidebar.style.pointerEvents = "auto";
          }, 100);
        }
        return originalNavigate.apply(this, args);
      };
    }
  }

  // Intercept all link clicks to prevent same-page navigation
  function interceptLinkClicks() {
    document.addEventListener(
      "click",
      function (e) {
        const target = e.target;
        const link = target.closest("a");

        if (link && link.href) {
          const linkUrl = new URL(link.href);

          // If the link is external, do not intercept it
          if (linkUrl.hostname !== window.location.hostname) {
            return;
          }

          const linkPath = linkUrl.pathname;
          const currentPath = window.location.pathname;

          // Normalize paths for comparison
          const normalizedLinkPath = linkPath.endsWith("/") ? linkPath.slice(0, -1) : linkPath;
          const normalizedCurrentPath = currentPath.endsWith("/") ? currentPath.slice(0, -1) : currentPath;
          const hasHash = typeof linkUrl.hash === "string" && linkUrl.hash.length > 1;

          // If clicking on the same page, prevent navigation
          if (normalizedLinkPath === normalizedCurrentPath && !hasHash) {
            e.preventDefault();
            e.stopPropagation();
            return false;
          }
        }
      },
      true
    );
  }

  // Override history methods to prevent unnecessary navigation
  function overrideHistoryMethods() {
    const originalPushState = history.pushState;
    const originalReplaceState = history.replaceState;

    history.pushState = function (...args) {
      const newPath = args[2];
      if (newPath && newPath !== currentPage) {
        currentPage = newPath;
        return originalPushState.apply(history, args);
      }
      // Don't push state if it's the same page
      return;
    };

    history.replaceState = function (...args) {
      const newPath = args[2];
      if (newPath && newPath !== currentPage) {
        currentPage = newPath;
        return originalReplaceState.apply(history, args);
      }
      // Don't replace state if it's the same page
      return;
    };
  }

  // Prevent Astro from triggering unnecessary events
  function preventAstroEvents() {
    // Override Astro's internal navigation
    if (window.Astro) {
      const originalNavigate = window.Astro.navigate;
      if (originalNavigate) {
        window.Astro.navigate = function (url) {
          const currentPath = window.location.pathname;
          const normalizedCurrentPath = currentPath.endsWith("/") ? currentPath.slice(0, -1) : currentPath;
          const normalizedUrl = url.endsWith("/") ? url.slice(0, -1) : url;

          // Only navigate if it's a different page
          if (normalizedCurrentPath !== normalizedUrl) {
            return originalNavigate.call(this, url);
          }
          return Promise.resolve();
        };
      }
    }
  }

  function setupTableOfContentsEnhancements() {
    if (cleanupTOCListeners) {
      cleanupTOCListeners();
      cleanupTOCListeners = null;
    }

    const tocElement = document.querySelector("starlight-toc");
    if (!tocElement) {
      return;
    }

    const tocLinks = Array.from(tocElement.querySelectorAll("a")).filter((link) => !!link.hash);
    if (!tocLinks.length) {
      return;
    }

    tocLinks.forEach((link) => link.removeAttribute("aria-current"));

    const ensureOverviewSentinel = () => {
      let sentinel = document.getElementById("toc-overview-sentinel");
      if (sentinel) return sentinel;
      const main = document.querySelector("main");
      if (!main) return null;
      sentinel = document.createElement("span");
      sentinel.id = "toc-overview-sentinel";
      sentinel.setAttribute("aria-hidden", "true");
      sentinel.style.position = "relative";
      sentinel.style.display = "block";
      sentinel.style.width = "0px";
      sentinel.style.height = "1px";
      sentinel.style.margin = "0";
      sentinel.style.padding = "0";
      main.insertBefore(sentinel, main.firstChild || null);
      return sentinel;
    };

    const resolveHeading = (link, index) => {
      const rawHash = decodeURIComponent(link.hash.slice(1));
      const fallbackIds = index === 0 ? [rawHash, "page-title", tocElement.dataset.pageId].filter(Boolean) : [rawHash];

      for (const targetId of fallbackIds) {
        if (!targetId) continue;
        const candidate = document.getElementById(targetId);
        if (candidate) {
          if (candidate.id !== rawHash && candidate.id) {
            link.hash = `#${candidate.id}`;
          }
          return candidate;
        }
      }

      // If still not found, attempt to locate by data attributes
      if (rawHash) {
        const dataMatch = document.querySelector(`[data-slug="${escapeCSS(rawHash)}"]`);
        if (dataMatch instanceof HTMLElement) {
          if (dataMatch.id && dataMatch.id !== rawHash) {
            link.hash = `#${dataMatch.id}`;
          } else if (!dataMatch.id) {
            dataMatch.id = rawHash;
          }
          return dataMatch;
        }
      }

      if (index === 0) {
        const sentinel = ensureOverviewSentinel();
        if (sentinel) {
          link.hash = "#toc-overview-sentinel";
          return sentinel;
        }
      }

      return null;
    };

    const headingEntries = tocLinks
      .map((link, index) => {
        const heading = resolveHeading(link, index);
        if (!heading) return null;
        return { link, heading };
      })
      .filter(Boolean);

    if (!headingEntries.length) {
      return;
    }

    const headingSet = new Set(headingEntries.map(({ heading }) => heading));

    let activeLink = tocElement.querySelector('a[aria-current="true"]') || null;
    const getOffset = () => (document.querySelector("header")?.getBoundingClientRect().height || 0) + 24;

    const setActiveLink = (link) => {
      if (!link) return;

      if (link === activeLink && link.hasAttribute("aria-current")) {
        return;
      }

      tocLinks.forEach((l) => {
        if (l !== link && l.hasAttribute("aria-current")) {
          l.removeAttribute("aria-current");
        }
      });

      if (activeLink && activeLink !== link) {
        activeLink.removeAttribute("aria-current");
      }

      link.setAttribute("aria-current", "true");
      activeLink = link;
    };

    const fallbackActive = () => {
      const offset = getOffset();
      let lastAbove = null;
      let firstBelow = null;

      for (const { heading, link } of headingEntries) {
        const top = heading.getBoundingClientRect().top - offset;
        if (top <= 0) {
          lastAbove = link;
        } else {
          firstBelow = firstBelow || link;
          break;
        }
      }

      return lastAbove || firstBelow || headingEntries[0]?.link || null;
    };

    const visibleMap = new Map();
    let observer = null;

    const updateActiveLink = () => {
      let nextActive = null;

      for (const { heading, link } of headingEntries) {
        if (visibleMap.get(heading)) {
          nextActive = link;
          break;
        }
      }

      if (!nextActive) {
        nextActive = fallbackActive();
      }

      const bottomThreshold = Math.max(40, window.innerHeight * 0.1);
      const scrolledBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - bottomThreshold;
      if (scrolledBottom) {
        const lastEntry = headingEntries[headingEntries.length - 1];
        if (lastEntry) {
          nextActive = lastEntry.link;
        }
      }

      setActiveLink(nextActive);
    };

    const initObserver = () => {
      const offset = getOffset();
      if (observer) observer.disconnect();
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (!headingSet.has(entry.target)) return;
            visibleMap.set(entry.target, entry.isIntersecting && entry.intersectionRatio > 0);
          });
          updateActiveLink();
        },
        {
          root: null,
          rootMargin: `-${offset}px 0px -55%`,
          threshold: [0, 0.2, 0.5, 0.9],
        }
      );

      headingEntries.forEach(({ heading }) => observer.observe(heading));
    };

    initObserver();
    updateActiveLink();

    const handleResize = throttle(() => {
      initObserver();
      updateActiveLink();
    }, 200);

    const handleScroll = throttle(() => {
      updateActiveLink();
    }, 120);

    window.addEventListener("resize", handleResize);
    window.addEventListener("scroll", handleScroll, { passive: true });

    cleanupTOCListeners = () => {
      window.removeEventListener("resize", handleResize);
      window.removeEventListener("scroll", handleScroll);
      if (observer) observer.disconnect();
    };
  }

  function scheduleTOCSetup(attempt = 0) {
    requestAnimationFrame(() => {
      if (!document.querySelector("starlight-toc")) {
        if (attempt < 5) {
          setTimeout(() => scheduleTOCSetup(attempt + 1), 80);
        }
        return;
      }
      setupTableOfContentsEnhancements();
    });
  }

  // Initial setup
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => {
      preventLoadingEffects();
      preventAstroRerenders();
      interceptLinkClicks();
      overrideHistoryMethods();
      preventAstroEvents();
      scheduleTOCSetup();
    });
  } else {
    preventLoadingEffects();
    preventAstroRerenders();
    interceptLinkClicks();
    overrideHistoryMethods();
    preventAstroEvents();
    scheduleTOCSetup();
  }

  // Listen for Astro events
  document.addEventListener("astro:page-load", () => {
    applyStoredTheme();
    handlePageLoad();
    scheduleTOCSetup();
  });
  document.addEventListener("astro:after-swap", () => {
    applyStoredTheme();
    handleAfterSwap();
    scheduleTOCSetup();
  });

  // Additional event listeners to prevent re-renders
  document.addEventListener("astro:before-swap", (event) => {
    const nextDoc = event?.newDocument || event?.detail?.newDocument;
    if (nextDoc) {
      applyStoredTheme(nextDoc);
    }
    // Prevent any visual changes during swap
    const sidebar = document.querySelector(".sidebar-nav");
    if (sidebar) {
      sidebar.style.opacity = "1";
      sidebar.style.visibility = "visible";
    }
    if (cleanupTOCListeners) {
      cleanupTOCListeners();
      cleanupTOCListeners = null;
    }
  });

  // Ensure sidebar stability during all navigation events
  const navigationEvents = ["popstate", "pushstate", "replacestate"];
  navigationEvents.forEach((event) => {
    window.addEventListener(event, () => {
      setTimeout(() => {
        preventLoadingEffects();
      }, 0);
    });
  });

  // Monitor for any Astro navigation attempts and prevent same-page navigation
  let lastNavigationTime = 0;
  document.addEventListener("astro:before-preparation", () => {
    const now = Date.now();
    if (now - lastNavigationTime < 100) {
      // Prevent rapid navigation attempts
      return;
    }
    lastNavigationTime = now;
  });
})();

window.StarlightThemeProvider = (() => {
	const storedTheme =
		typeof localStorage !== 'undefined' && localStorage.getItem('starlight-theme');
	const theme =
		storedTheme ||
		(window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
	document.documentElement.dataset.theme = theme === 'light' ? 'light' : 'dark';
	return {
		updatePickers(theme = storedTheme || 'auto') {
			document.querySelectorAll('starlight-theme-select').forEach((picker) => {
				const select = picker.querySelector('select');
				if (select) select.value = theme;
				/** @type {HTMLTemplateElement | null} */
				const tmpl = document.querySelector(`#theme-icons`);
				const newIcon = tmpl && tmpl.content.querySelector('.' + theme);
				if (newIcon) {
					const oldIcon = picker.querySelector('svg.label-icon');
					if (oldIcon) {
						oldIcon.replaceChildren(...newIcon.cloneNode(true).childNodes);
					}
				}
			});
		},
	};
})();

