(function(){const darkLogoSrc = "/@fs/C:/Users/ASD/yourgpt-docs-latest/src/assets/yourgpt-white.svg?origWidth=72&origHeight=33&origFormat=svg";
const lightLogoSrc = "/@fs/C:/Users/ASD/yourgpt-docs-latest/src/assets/yourgpt-dark.svg?origWidth=72&origHeight=33&origFormat=svg";

  const logo = document.getElementById('site-logo');
  if (!logo) {
    return;
  }

  const resolvePreferredTheme = () => {
    const root = document.documentElement;

    if (root.dataset.theme) {
      return root.dataset.theme === 'dark';
    }

    if (root.classList.contains('dark')) {
      return true;
    }

    if (root.classList.contains('light')) {
      return false;
    }

    try {
      const storedTheme = localStorage.getItem('starlight.theme');
      if (storedTheme === 'dark' || storedTheme === 'light') {
        return storedTheme === 'dark';
      }
    } catch (_error) {
      /* ignore access issues */
    }

    return window.matchMedia?.('(prefers-color-scheme: dark)')?.matches ?? false;
  };

  const applyLogo = () => {
    const isDarkMode = resolvePreferredTheme();
    const nextSrc = isDarkMode ? darkLogoSrc : lightLogoSrc;

    if (logo.getAttribute('src') !== nextSrc) {
      logo.setAttribute('src', nextSrc);
    }

    logo.setAttribute('data-theme-applied', isDarkMode ? 'dark' : 'light');
  };

  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (
        mutation.type === 'attributes' &&
        (mutation.attributeName === 'class' || mutation.attributeName === 'data-theme')
      ) {
        applyLogo();
        break;
      }
    }
  });

  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class', 'data-theme'],
  });

  const mediaQuery = window.matchMedia?.('(prefers-color-scheme: dark)') ?? null;
  const handleMediaChange = () => applyLogo();

  if (mediaQuery) {
    if (typeof mediaQuery.addEventListener === 'function') {
      mediaQuery.addEventListener('change', handleMediaChange);
    } else if (typeof mediaQuery.addListener === 'function') {
      mediaQuery.addListener(handleMediaChange);
    }
  }

  document.addEventListener('astro:after-swap', applyLogo);
  document.addEventListener('astro:before-swap', () => {
    observer.disconnect();

    if (mediaQuery) {
      if (typeof mediaQuery.removeEventListener === 'function') {
        mediaQuery.removeEventListener('change', handleMediaChange);
      } else if (typeof mediaQuery.removeListener === 'function') {
        mediaQuery.removeListener(handleMediaChange);
      }
    }
  });
  applyLogo();
})();
